"    if (typeof document === 'undefined') return candidates;

    // 0. Test Sandbox scope isolation (when current focus is inside test sandbox)
    var sandbox = document.getElementById('test-spatial-sandbox');
    if (sandbox && state.currentFocus && sandbox.contains(state.currentFocus)) {
      var sbItems = sandbox.querySelectorAll(CONFIG.navigableSelector);
      for (var s = 0; s < sbItems.length; s++) {
        if (isNavigable(sbItems[s])) candidates.push(sbItems[s]);
      }
      return candidates;
    }

    // 1. Persistent Header items (if header is not hidden)
    var header = document.querySelector(CONFIG.headerSelector);
    if (header && !header.classList.contains(CONFIG.headerHiddenClass)) {
      var headerItems = header.querySelectorAll(CONFIG.navigableSelector);
      for (var h = 0; h < headerItems.length; h++) {
        if (isNavigable(headerItems[h])) candidates.push(headerItems[h]);
      }
    }

    // 2. Active View items
    var activeView = document.querySelector(CONFIG.activeViewSelector);
    if (activeView) {
      var viewItems = activeView.querySelectorAll(CONFIG.navigableSelector);
      for (var v = 0; v < viewItems.length; v++) {
        if (isNavigable(viewItems[v])) candidates.push(viewItems[v]);
      }
    }

    // 3. Test Sandbox items (if present and not inside activeView)
    if (sandbox && (!activeView || !activeView.contains(sandbox))) {
      var extraSbItems = sandbox.querySelectorAll(CONFIG.navigableSelector);
      for (var es = 0; es < extraSbItems.length; es++) {
        if (isNavigable(extraSbItems[es])) candidates.push(extraSbItems[es]);
      }
    }

    return candidates;"

